class ReportInputError extends Error {}
function parsePriceList(text) {
  const items = [];
  for (const raw of (text || "").split("\n")) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const parts = line.split(";").map((p) => p.trim());
    if (parts.length < 3) continue;
    const [code, leistung, preisText] = parts;
    const preis = Number(preisText.replace(/\s|€/g, "").replace(",", "."));
    if (!leistung || !Number.isFinite(preis)) continue;
    items.push({ id: `P${items.length + 1}`, code, leistung, preis });
  }
  return items;
}
function validateInput(body) {
  const transcript = typeof body?.transcript === "string" ? body.transcript.trim() : "";
  const notes = typeof body?.notes === "string" ? body.notes.trim() : "";
  const species = typeof body?.species === "string" ? body.species.trim() : "";

  if (transcript.length < 20) {
    throw new ReportInputError("Das Transkript ist zu kurz für einen Bericht.");
  }
  if (transcript.length + notes.length > MAX_TRANSCRIPT_CHARS) {
    throw new ReportInputError("Das Transkript ist zu lang. Bitte auf eine Behandlung beschränken.");
  }
  return { transcript, notes, species };
}
function buildPracticeContext(settings) {
  const prices = parsePriceList(settings.preisliste);
  const priceLines = prices.length
    ? prices.map((p) => `${p.id}: ${p.code ? p.code + " – " : ""}${p.leistung}`).join("\n")
    : "(keine Preisliste hinterlegt)";
  return [
    `Land: ${settings.land === "DE" ? "Deutschland (GOT)" : "Österreich"}`,
    `Ton der Besitzerinfo: ${settings.tonBesitzerinfo || "freundlich, Sie-Form"}`,
    `<abkuerzungen>\n${settings.abkuerzungen || "(keine)"}\n</abkuerzungen>`,
    `<preisliste>\n${priceLines}\n</preisliste>`,
  ].join("\n\n");
}
function buildUserMessage({ transcript, notes, species }) {
  const parts = [];
  if (species) parts.push(`Tierart laut Praxis: ${species}`);
  if (notes) parts.push(`<notizen>\n${notes}\n</notizen>`);
  parts.push(`<transkript>\n${transcript}\n</transkript>`);
  return parts.join("\n\n");
}

const body = $input.first().json.body || {};
let input;
try {
  input = validateInput(body);
} catch (err) {
  return [{ json: { ok: false, status: 400, body: { error: err.message } } }];
}

return [{
  json: {
    ok: true,
    settings: SETTINGS,
    prices: parsePriceList(SETTINGS.preisliste),
    request: {
      model: MODEL,
      max_tokens: 16000,
      fallbacks: "default",
      output_config: { effort: "medium", format: { type: "json_schema", schema: OUTPUT_SCHEMA } },
      system: [
        { type: "text", text: SYSTEM_PROMPT },
        { type: "text", text: buildPracticeContext(SETTINGS), cache_control: { type: "ephemeral" } },
      ],
      messages: [{ role: "user", content: buildUserMessage(input) }],
    },
  },
}];

// Baut die 7 Dokumente. Preise und Summen kommen aus der Preisliste, nicht von der KI.
// Turns the structured AI report into the seven editable document drafts.
// Pure functions: used in the browser and in the Node tests.
// Prices and totals are computed here from the practice price list, never by the AI.

const DOC_LABELS = {
  bericht: "Behandlungsbericht",
  besitzerinfo: "Besitzerinfo",
  rechnung: "Rechnungsentwurf",
  kostenvoranschlag: "Kostenvoranschlag",
  versicherung: "Versicherungspaket",
  ueberweisung: "Überweisung",
  erinnerung: "Erinnerungen",
};

function money(value) {
  return value.toLocaleString("de-AT", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " €";
}

const round2 = (n) => Math.round(n * 100) / 100;

function resolvePositions(positions, prices) {
  const byId = new Map(prices.map((p) => [p.id, p]));
  return positions.map((pos) => {
    const menge = Number.isFinite(pos.menge) && pos.menge > 0 ? pos.menge : 1;
    const item = byId.get(pos.preisliste_id);
    if (!item) return { leistung: pos.leistung, code: "", menge, einzel: null, summe: null };
    return { leistung: item.leistung, code: item.code, menge, einzel: item.preis, summe: round2(item.preis * menge) };
  });
}

function totals(lines, ustSatz) {
  const netto = round2(lines.reduce((sum, l) => sum + (l.summe ?? 0), 0));
  const ust = round2((netto * ustSatz) / 100);
  return { netto, ust, brutto: round2(netto + ust), offen: lines.filter((l) => l.summe === null).length };
}

function header(settings) {
  return [settings.praxisName, settings.praxisAdresse].filter(Boolean).join("\n");
}

function signalement(p) {
  const parts = [p.tierart, p.rasse, p.alter, p.gewicht && `${p.gewicht}`].filter(Boolean);
  return `${p.name || "Patient"}${parts.length ? " (" + parts.join(", ") + ")" : ""}`;
}

function positionTable(lines, settings) {
  const rows = lines.map((l) => {
    const code = l.code ? `[${l.code}] ` : "";
    const preis = l.summe === null ? "Preis offen" : `${l.menge} × ${money(l.einzel)} = ${money(l.summe)}`;
    return `- ${code}${l.leistung}: ${preis}`;
  });
  const t = totals(lines, settings.ustSatz);
  rows.push("", `Netto: ${money(t.netto)}`, `USt ${settings.ustSatz} %: ${money(t.ust)}`, `Gesamt: ${money(t.brutto)}`);
  if (t.offen) rows.push(`Achtung: ${t.offen} Position(en) ohne Preis, bitte ergänzen.`);
  return rows.join("\n");
}

function medList(meds) {
  return meds.map((m) => `- ${[m.name, m.dosis, m.anwendung].filter(Boolean).join(", ")}`).join("\n");
}

function buildDocuments(report, settings, prices, date = new Date()) {
  const r = report;
  const datum = date.toLocaleDateString("de-AT");
  const kopf = header(settings);
  const halter = r.patient.halter ? `Tierhalter/in: ${r.patient.halter}\n` : "";
  const leistungen = resolvePositions(r.leistungen, prices);
  const unterschrift = settings.tierarztName ? `\n\n${settings.tierarztName}` : "";

  const docs = {};

  docs.bericht = [
    `Datum: ${datum}`,
    `Patient: ${signalement(r.patient)}`,
    halter.trim(),
    "",
    `S – Subjektiv:\n${r.soap.subjektiv || "–"}`,
    `O – Objektiv:\n${r.soap.objektiv || "–"}`,
    `A – Assessment:\n${r.soap.assessment || "–"}`,
    `P – Plan:\n${r.soap.plan || "–"}`,
    r.diagnosen.length ? `Diagnosen:\n${r.diagnosen.map((d) => `- ${d}`).join("\n")}` : "",
    r.medikamente.length ? `Medikamente:\n${medList(r.medikamente)}` : "",
  ]
    .filter((s) => s !== "")
    .join("\n\n");

  docs.besitzerinfo = [
    kopf,
    `Informationen zur Behandlung von ${r.patient.name || "Ihrem Tier"} am ${datum}`,
    r.besitzer_info,
    r.medikamente.length ? `Ihre Medikamente:\n${medList(r.medikamente)}` : "",
    r.erinnerungen.length ? `Nächste Termine:\n${r.erinnerungen.map((e) => `- ${e.anlass}: ${e.wann}`).join("\n")}` : "",
    unterschrift.trim(),
  ]
    .filter(Boolean)
    .join("\n\n");

  docs.rechnung = [
    kopf,
    `RECHNUNGSENTWURF – ${datum}`,
    `${halter}Patient: ${signalement(r.patient)}`,
    leistungen.length ? positionTable(leistungen, settings) : "Keine Leistungen erkannt.",
  ]
    .filter(Boolean)
    .join("\n\n");

  if (r.kostenvoranschlag.erforderlich) {
    const kv = resolvePositions(r.kostenvoranschlag.positionen, prices);
    docs.kostenvoranschlag = [
      kopf,
      `KOSTENVORANSCHLAG – ${datum}`,
      `${halter}Patient: ${signalement(r.patient)}`,
      `Anlass: ${r.kostenvoranschlag.anlass}`,
      kv.length ? positionTable(kv, settings) : "Positionen bitte ergänzen.",
      r.kostenvoranschlag.hinweis ? `Hinweis: ${r.kostenvoranschlag.hinweis}` : "",
      "Dieser Kostenvoranschlag ist unverbindlich. Abweichungen sind je nach Befund möglich.",
      unterschrift.trim(),
    ]
      .filter(Boolean)
      .join("\n\n");
  }

  docs.versicherung = [
    kopf,
    `Behandlungsbestätigung für die Tierkrankenversicherung – ${datum}`,
    `${halter}Patient: ${signalement(r.patient)}`,
    `Diagnose:\n${r.versicherung.diagnose_klartext || r.diagnosen.join(", ") || "–"}`,
    `Durchgeführte Behandlung:\n${r.versicherung.behandlung_klartext || "–"}`,
    leistungen.length ? `Abgerechnete Leistungen:\n${positionTable(leistungen, settings)}` : "",
    unterschrift.trim(),
  ]
    .filter(Boolean)
    .join("\n\n");

  if (r.ueberweisung.erforderlich) {
    docs.ueberweisung = [
      kopf,
      `An: ${r.ueberweisung.empfaenger || "(Empfänger ergänzen)"}`,
      `Überweisung – ${datum}`,
      `Patient: ${signalement(r.patient)}`,
      `Fragestellung: ${r.ueberweisung.fragestellung || "–"}`,
      r.ueberweisung.brief,
      unterschrift.trim(),
    ]
      .filter(Boolean)
      .join("\n\n");
  }

  if (r.erinnerungen.length) {
    docs.erinnerung = r.erinnerungen
      .map((e) => `- ${r.patient.name || "Patient"}: ${e.anlass} – ${e.wann}`)
      .join("\n");
  }

  return docs;
}


const response = $input.first().json;
const prep = $('Eingabe prüfen').first().json;

if (response.stop_reason === "refusal") {
  return [{ json: { status: 502, body: { error: "Die KI hat die Anfrage abgelehnt." } } }];
}
const textBlock = (response.content || []).find((b) => b.type === "text");
let report;
try {
  if (response.stop_reason === "max_tokens" || !textBlock) throw new Error("incomplete");
  report = JSON.parse(textBlock.text);
} catch {
  return [{ json: { status: 502, body: { error: "Die Unterlagen konnten nicht vollständig erstellt werden." } } }];
}

const documents = buildDocuments(report, prep.settings, prep.prices);
return [{
  json: {
    status: 200,
    body: { report, settings: prep.settings, prices: prep.prices, documents, pruefliste: report.pruefliste },
  },
}];

// Fehler der Claude API in eine verständliche Antwort übersetzen.
const err = $input.first().json.error;
const text = typeof err === "string" ? err : JSON.stringify(err || {});
const status = Number((err && (err.httpCode || err.status)) || (text.match(/\b(4\d\d|5\d\d)\b/) || [])[1] || 0);
let message = "Die KI ist gerade nicht erreichbar. Bitte nochmal versuchen.";
if (status === 401) message = "API-Key fehlt oder ist ungültig (Zugangsdaten im Knoten 'Claude API' prüfen).";
if (status === 429) message = "Gerade zu viele Anfragen. Bitte gleich nochmal versuchen.";
return [{ json: { status: 502, body: { error: message } } }];

// Freigabe protokollieren: wer, wann, welche Dokumente, geändert ja/nein.
// Inhalte werden nur als SHA-256-Prüfsumme gespeichert.
// Hinweis: Workflow-Static-Data wird nur bei aktivem Workflow (Produktions-URL) gespeichert.
const DOC_TYPES = ["bericht","besitzerinfo","rechnung","kostenvoranschlag","versicherung","ueberweisung","erinnerung"];
function sha256Hex(message) {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01,
    0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
    0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
    0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08,
    0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const bytes = Array.from(new TextEncoder().encode(message));
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push(Math.floor(bitLen / 2 ** (i * 8)) & 0xff);
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  const W = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      W[t] = (bytes[off + 4 * t] << 24) | (bytes[off + 4 * t + 1] << 16) | (bytes[off + 4 * t + 2] << 8) | bytes[off + 4 * t + 3];
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      const s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const t1 = (h + S1 + ((e & f) ^ (~e & g)) + K[t] + W[t]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const t2 = (S0 + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      [h, g, f, e, d, c, b, a] = [g, f, e, (d + t1) | 0, c, b, a, (t1 + t2) | 0];
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map((x) => (x >>> 0).toString(16).padStart(8, "0")).join("");
}

const body = $input.first().json.body || {};
const tierarzt = typeof body.tierarzt === "string" ? body.tierarzt.trim() : "";
const docs = body.documents && typeof body.documents === "object" ? body.documents : {};
const fail = (error) => [{ json: { status: 400, body: { error } } }];
if (!tierarzt) return fail("Bitte den Namen des freigebenden Tierarztes angeben.");

const documents = [];
for (const type of DOC_TYPES) {
  const doc = docs[type];
  if (!doc) continue;
  if (typeof doc.final !== "string" || typeof doc.draft !== "string") return fail("Dokument " + type + " ist unvollständig.");
  documents.push({ type, edited: doc.final.trim() !== doc.draft.trim(), hash: sha256Hex(doc.final) });
}
if (documents.length === 0) return fail("Keine Dokumente zur Freigabe.");

const entry = {
  id: $execution.id + "-" + Date.now(),
  approvedAt: new Date().toISOString(),
  tierarzt: tierarzt.slice(0, 200),
  documents,
};
const store = $getWorkflowStaticData("global");
store.freigaben = (store.freigaben || []).concat(entry).slice(-1000);
return [{ json: { status: 200, body: { approval: entry } } }];

// Letzte 50 Freigaben, neueste zuerst.
const store = $getWorkflowStaticData("global");
const approvals = (store.freigaben || []).slice(-50).reverse();
return [{ json: { status: 200, body: { approvals } } }];
